#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int N;
int pairs[64][2]; int npairs;
int adj[16];
int term[3];
int colors[16];

int colorable_internal(int idx, int nint, int *internals){
    if(idx==nint) return 1;
    int v=internals[idx];
    for(int c=0;c<3;c++){
        int ok=1;
        int a=adj[v];
        for(int u=0;u<N;u++) if((a>>u)&1){ if(colors[u]==c){ok=0;break;} }
        if(ok){ colors[v]=c; if(colorable_internal(idx+1,nint,internals)) return 1; colors[v]=-1; }
    }
    return 0;
}

int main(int argc,char**argv){
    N=atoi(argv[1]);
    npairs=0;
    for(int i=0;i<N;i++)for(int j=i+1;j<N;j++){pairs[npairs][0]=i;pairs[npairs][1]=j;npairs++;}
    long long total=1LL<<npairs;
    int internals[16]; int nint=0;
    for(int v=3;v<N;v++) internals[nint++]=v;
    int found=0;
    for(long long mask=0; mask<total; mask++){
        memset(adj,0,sizeof(adj));
        for(int k=0;k<npairs;k++) if((mask>>k)&1){int u=pairs[k][0],v=pairs[k][1];adj[u]|=1<<v;adj[v]|=1<<u;}
        int good=1;
        for(int a=0;a<2 && good;a++)for(int b=0;b<2 && good;b++)for(int c=0;c<2 && good;c++){
            for(int i=0;i<N;i++)colors[i]=-1;
            colors[0]=a;colors[1]=b;colors[2]=c;
            int col=colorable_internal(0,nint,internals);
            int allF=(a==0&&b==0&&c==0); // 0 = F
            if(allF){ if(col) good=0; }
            else { if(!col) good=0; }
        }
        if(good){
            found++;
            printf("SOLUTION N=%d mask=%lld edges:",N,mask);
            for(int k=0;k<npairs;k++) if((mask>>k)&1) printf(" (%d,%d)",pairs[k][0],pairs[k][1]);
            printf("\n");
            if(found>=10){ printf("...more\n"); return 0;}
        }
    }
    printf("N=%d found=%d\n",N,found);
    return 0;
}
