#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int N;
int pu[128],pv[128]; int npairs;
int adj[32];
int internals[32]; int nint;
int colors[32];

int bt(int idx){
    if(idx==nint) return 1;
    int v=internals[idx];
    for(int c=0;c<3;c++){
        int a=adj[v]; int ok=1;
        for(int u=0;u<N;u++) if((a>>u)&1){ if(colors[u]==c){ok=0;break;} }
        if(ok){ colors[v]=c; if(bt(idx+1)) return 1; colors[v]=-1; }
    }
    return 0;
}

int check(){
    // 7 good assignments must be colorable; all-0 must not
    for(int a=0;a<2;a++)for(int b=0;b<2;b++)for(int c=0;c<2;c++){
        for(int i=0;i<N;i++)colors[i]=-1;
        colors[0]=a;colors[1]=b;colors[2]=c;
        int col=bt(0);
        if(a==0&&b==0&&c==0){ if(col) return 0; }
        else { if(!col) return 0; }
    }
    return 1;
}

int main(int argc,char**argv){
    N=atoi(argv[1]);
    int trials=atoi(argv[2]);
    srand(atoi(argv[3]));
    npairs=0;
    for(int i=0;i<N;i++)for(int j=i+1;j<N;j++){ if(i<3&&j<3) continue; pu[npairs]=i;pv[npairs]=j;npairs++; }
    nint=0; for(int v=3;v<N;v++) internals[nint++]=v;
    for(int t=0;t<trials;t++){
        memset(adj,0,sizeof(adj));
        double p = 0.15 + 0.7*(rand()%1000)/1000.0;
        for(int k=0;k<npairs;k++) if((rand()%1000)/1000.0 < p){int u=pu[k],v=pv[k];adj[u]|=1<<v;adj[v]|=1<<u;}
        if(check()){
            printf("FOUND N=%d edges:",N);
            for(int k=0;k<npairs;k++){int u=pu[k],v=pv[k]; if((adj[u]>>v)&1) printf(" (%d,%d)",u,v);}
            printf("\n");
            return 0;
        }
    }
    printf("N=%d not found in %d trials\n",N,trials);
    return 0;
}
EOF
